@app.route('/calculate_strength', methods=['POST'])
def calculate_strength():
    password = request.form.get('password', '')
    length = len(password)
    uppercase = any(c.isupper() for c in password)
    lowercase = any(c.islower() for c in password)
    digit = any(c.isdigit() for c in password)
    symbol = any(c in "!@#$%^&*()_+-=" for c in password)

    strength_score = 0
    if length >= 8:
        strength_score += 1
    if uppercase:
        strength_score += 1
    if lowercase:
        strength_score += 1
    if digit:
        strength_score += 1
    if symbol:
        strength_score += 1

    level = ''
    if strength_score <= 2:
        level = 'Weak'
    elif strength_score <= 4:
        level = 'Moderate'
    else:
        level = 'Strong'

    template = Template("Your <b>password</b> strength is: <span style=\"color: blue;\">{{ level }}</span>", autoescape=True)

    return template.render(level=level)

