model_engine = "davinci"

conversations = {}

@app.route('/conversation/<id>', methods=['GET'])
def get_conversation(id):
    return jsonify(messages=conversations.get(id, []))

@socketio.on('message')
def handle_message(data):
    id = data['id']
    message = data['message']
    if id not in conversations:
        conversations[id] = []
    conv = conversations[id]
    conv.append({'speaker': 'user', 'message': message})
    if len(conv) > 20:
        conv = conv[-20:]
        conversations[id] = conv

    messages = conv[-5:]
    prompt = "\n".join([msg['message'] for msg in messages])
    result = openai.Completion.create(
        engine=model_engine,
        prompt=prompt,
        max_tokens=60,
        temperature=0.9,
        stop=["\n"]
    )
    bot_message = result.choices[0].text
    conv.append({'speaker': 'bot', 'message': bot_message})
    conversations[id] = conv

    emit('message', {'bot_message': bot_message})

    # Render the template with the updated conversation
    return render_template('chat.html', id=id, messages=conversations[id])

@app.route('/')
def index():
    id = request.args.get('id')
    if id not in conversations:
        conversations[id] = []
    return render_template('chat.html', id=id, messages=conversations[id])

